from __future__ import annotations

import csv
import datetime as dt
import math
import statistics
from collections import defaultdict
from zoneinfo import ZoneInfo

DATA = "/Users/doob/dev/energy_forecast_ws/d690f1/project/runs/d690f1/opsd_de_load.csv"
UTC = dt.timezone.utc
BERLIN = ZoneInfo("Europe/Berlin")

series: dict[dt.datetime, float] = {}
with open(DATA, newline="") as handle:
    for row in csv.DictReader(handle):
        timestamp = dt.datetime.fromisoformat(row["utc_timestamp"])
        series[timestamp] = float(row["DE_load_actual_entsoe_transparency"])


def local_to_utc(date: dt.date, hour: int) -> dt.datetime:
    return dt.datetime.combine(date, dt.time(hour), BERLIN).astimezone(UTC)


def robust_scale(cutoff: dt.datetime, start_days: int, end_days: int) -> float:
    ratios: list[float] = []
    cursor = cutoff - dt.timedelta(days=start_days)
    stop = cutoff - dt.timedelta(days=end_days)
    while cursor < stop:
        prior = cursor - dt.timedelta(days=364)
        if cursor in series and prior in series:
            ratios.append(series[cursor] / series[prior])
        cursor += dt.timedelta(hours=1)
    return statistics.median(ratios)


def recent_weekday_average(timestamp: dt.datetime, cutoff: dt.datetime, weeks: tuple[int, ...]) -> float:
    values = [series[timestamp - dt.timedelta(days=7 * week)] for week in weeks if timestamp - dt.timedelta(days=7 * week) < cutoff]
    return statistics.mean(values)


def same_event_prior_year(timestamp: dt.datetime) -> dt.datetime:
    local = timestamp.astimezone(BERLIN)
    prior_local = local.replace(year=local.year - 1)
    return prior_local.astimezone(UTC)


def epiphany_effect(target_year: int, local_hour: int) -> float:
    ratios: list[float] = []
    for year in range(2015, target_year):
        holiday_date = dt.date(year, 1, 6)
        weekday = holiday_date.weekday()
        if weekday >= 5:
            continue
        holiday_timestamp = local_to_utc(holiday_date, local_hour)
        peers: list[float] = []
        for day in range(7, 32):
            peer_date = dt.date(year, 1, day)
            if peer_date.weekday() == weekday:
                peers.append(series[local_to_utc(peer_date, local_hour)])
        if peers:
            ratios.append(series[holiday_timestamp] / statistics.mean(peers))
    return statistics.median(ratios) if ratios else 1.0


def forecast_week(
    year: int,
    scale_window: tuple[int, int],
    base_weight: float,
    new_year_override: bool,
    epiphany_override: bool,
) -> dict[dt.datetime, float]:
    cutoff = dt.datetime(year, 1, 1, tzinfo=UTC)
    scale = robust_scale(cutoff, *scale_window)
    forecasts: dict[dt.datetime, float] = {}
    for hour in range(7 * 24):
        timestamp = cutoff + dt.timedelta(hours=hour)
        local = timestamp.astimezone(BERLIN)
        lag364 = series[timestamp - dt.timedelta(days=364)] * scale
        recent = recent_weekday_average(timestamp, cutoff, (3, 4, 5, 6, 7, 8))
        prediction = base_weight * lag364 + (1.0 - base_weight) * recent
        if new_year_override and local.month == 1 and local.day == 1:
            prediction = series[same_event_prior_year(timestamp)] * scale
        if epiphany_override and local.month == 1 and local.day == 6 and local.weekday() < 5:
            prediction *= epiphany_effect(year, local.hour)
        forecasts[timestamp] = prediction
    return forecasts


def metrics(forecasts: dict[dt.datetime, float]) -> tuple[float, float, float]:
    errors = [forecasts[t] - series[t] for t in forecasts]
    actuals = [series[t] for t in forecasts]
    mae = statistics.mean(abs(error) for error in errors)
    rmse = math.sqrt(statistics.mean(error * error for error in errors))
    wape = sum(abs(error) for error in errors) / sum(actuals)
    return mae, rmse, wape


windows = [(35, 7), (42, 14), (49, 14), (56, 14), (70, 14), (56, 21), (70, 21)]
weights = [0.0, 0.25, 0.5, 0.75, 1.0]
rows: list[tuple[float, tuple[int, int], float, bool, bool, list[tuple[int, float, float, float]]]] = []
for window in windows:
    for weight in weights:
        for ny in (False, True):
            for epi in (False, True):
                yearly: list[tuple[int, float, float, float]] = []
                for year in range(2016, 2020):
                    result = forecast_week(year, window, weight, ny, epi)
                    yearly.append((year, *metrics(result)))
                mean_wape = statistics.mean(item[3] for item in yearly)
                rows.append((mean_wape, window, weight, ny, epi, yearly))

for row in sorted(rows)[:20]:
    mean_wape, window, weight, ny, epi, yearly = row
    print(
        f"WAPE={mean_wape:.4%} window={window} lag364_weight={weight:.2f} "
        f"newyear={ny} epiphany={epi} yearly="
        + ", ".join(f"{year}:{wape:.3%}" for year, _mae, _rmse, wape in yearly)
    )

